rollback.sql:
DO $$ BEGIN
 IF EXISTS (
  SELECT 1 FROM modeling_model_release_candidate
   WHERE origin <> 'SCHEMA_ONLY_INTENT'
     AND status NOT IN ('REJECTED','ROLLED_BACK','STALE','CANCELLED','PUBLISHED')
   GROUP BY tenant_id, plan_id HAVING count(*) > 1
 ) THEN
  RAISE EXCEPTION 'ROLLBACK_BLOCKED_MULTIPLE_ACTIVE_MODEL_CANDIDATES';
 END IF;
END $$;
CREATE UNIQUE INDEX uk_model_release_candidate_active_plan
 ON modeling_model_release_candidate (tenant_id, plan_id)
 WHERE origin <> 'SCHEMA_ONLY_INTENT'
   AND status NOT IN ('REJECTED','ROLLED_BACK','STALE','CANCELLED','PUBLISHED');
